import { useEffect, useRef, useCallback, useState } from 'react';

const DB_URL = 'https://vdgo-master-sync-default-rtdb.europe-west1.firebasedatabase.app';
const DEVICE_ID = 'vdgo_' + Math.random().toString(36).substring(2, 8);

const FIXED_ROOM = 'default';

export function useFirebaseSync(
  onData: (type: string, data: any) => void
) {
  const [status, setStatus] = useState<'offline' | 'connecting' | 'connected'>('offline');
  const [peerCount, setPeerCount] = useState(0);
  const dataHandlersRef = useRef(onData);
  const lastTimestampRef = useRef<number>(0);
  const myLastPushRef = useRef<number>(0);
  dataHandlersRef.current = onData;

  const roomUrl = (path: string) => `${DB_URL}/vdgo_rooms/${FIXED_ROOM}/${path}.json`;

  // Push only changes, not full state
  const pushData = useCallback(async () => {
    try {
      const now = Date.now();
      myLastPushRef.current = now;
      const data = {
        cases: localStorage.getItem('vdgo_cases') || '[]',
        notes: localStorage.getItem('vdgo_notes') || '[]',
        kpi: localStorage.getItem('vdgo_kpiSession') || '{}',
        kpiCases: localStorage.getItem('vdgo_kpiCases') || '[]',
        duties: localStorage.getItem('vdgo_duties') || '[]',
        cash: localStorage.getItem('vdgo_cash_registers_v1') || '[]',
        timesheets: localStorage.getItem('vdgo_timesheets') || '[]',
        dispatcher: localStorage.getItem('vdgo_dispatcher') || '[]',
        excelFiles: localStorage.getItem('vdgo_excel_files') || '[]',
        // Sync deleted KPI keys so all peers know about deletions
        deletedKpiKeys: localStorage.getItem('vdgo_deleted_kpi_keys') || '[]',
        timestamp: now,
        from: DEVICE_ID,
      };
      await fetch(roomUrl('data'), {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      await fetch(roomUrl('presence/' + DEVICE_ID), {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lastSeen: now }),
      });
    } catch (e) {
      console.error('[FB] push error:', e);
    }
  }, []);

  useEffect(() => {
    let destroyed = false;
    let localMutationTs = 0;
    setStatus('connecting');

    // Track when WE mutate data locally
    const trackLocalMutation = () => {
      localMutationTs = Date.now();
    };
    window.addEventListener('vdgo_data_changed', trackLocalMutation);

    // Global deleted KPI keys from all peers
    let globalDeletedKpiKeys: string[] = [];

    const loadData = async () => {
      try {
        const resp = await fetch(roomUrl('data'));
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        const val = await resp.json();
        if (!val || destroyed) return;
        if (val.from === DEVICE_ID) return;

        // Skip if data is older than what we've already processed
        if (val.timestamp && val.timestamp <= lastTimestampRef.current) return;
        if (val.timestamp) lastTimestampRef.current = val.timestamp;

        // CRITICAL: Skip if we mutated locally in the last 2 seconds
        // This prevents our changes from being overwritten by stale peer data
        if (Date.now() - localMutationTs < 2000) {
          console.log('[FB] Skipping sync - local mutation in progress');
          return;
        }

        console.log('[FB] Received data from', val.from);

        // Collect deleted KPI keys from peer
        if (val.deletedKpiKeys) {
          try {
            const peerDeleted = JSON.parse(val.deletedKpiKeys);
            if (Array.isArray(peerDeleted)) {
              globalDeletedKpiKeys = mergeDeletedKpiKeys(globalDeletedKpiKeys, peerDeleted);
            }
          } catch { /* */ }
        }

        // MERGE strategy: merge key-by-key instead of full overwrite
        try {
          if (val.cases) mergeData('cases', val.cases, dataHandlersRef.current);
          if (val.notes) mergeData('notes', val.notes, dataHandlersRef.current);
          if (val.kpi) mergeKpi(val.kpi, dataHandlersRef.current, globalDeletedKpiKeys);
          if (val.kpiCases) mergeData('kpiCases', val.kpiCases, dataHandlersRef.current);
          if (val.duties) mergeData('duties', val.duties, dataHandlersRef.current);
          if (val.cash) mergeData('cash', val.cash, dataHandlersRef.current);
          if (val.timesheets) mergeData('timesheets', val.timesheets, dataHandlersRef.current);
          if (val.dispatcher) mergeData('dispatcher', val.dispatcher, dataHandlersRef.current);
          if (val.excelFiles) mergeData('excelFiles', val.excelFiles, dataHandlersRef.current);
        } catch (e) {
          console.error('[FB] Parse error:', e);
        }
      } catch (e) {
        // Silently fail
      }
    };

    const checkPresence = async () => {
      try {
        const resp = await fetch(roomUrl('presence'));
        if (!resp.ok) return;
        const val = await resp.json() || {};
        const now = Date.now();
        for (const [key, entry] of Object.entries(val)) {
          const e = entry as any;
          if (e.lastSeen && now - e.lastSeen > 30000 && key !== DEVICE_ID) {
            try { await fetch(roomUrl('presence/' + key), { method: 'DELETE' }); } catch { /* */ }
            delete val[key];
          }
        }
        const count = Object.keys(val).length;
        setPeerCount(count);
        setStatus(count > 0 ? 'connected' : 'connecting');
      } catch (e) {
        // Silently fail
      }
    };

    const init = async () => {
      try {
        // Load our own deleted KPI keys
        try {
          const ourDeleted = JSON.parse(localStorage.getItem('vdgo_deleted_kpi_keys') || '[]');
          if (Array.isArray(ourDeleted)) globalDeletedKpiKeys = ourDeleted;
        } catch { /* */ }

        await fetch(roomUrl('presence/' + DEVICE_ID), {
          method: 'PUT',
          body: JSON.stringify({ lastSeen: Date.now() }),
        });
        await loadData();
        setStatus('connected');
      } catch (e) {
        setStatus('offline');
      }
    };

    init();

    // Reasonable polling - not too aggressive
    const dataInterval = setInterval(() => { if (!destroyed) loadData(); }, 1500);
    const presenceInterval = setInterval(() => { if (!destroyed) checkPresence(); }, 5000);
    const pushInterval = setInterval(() => { if (!destroyed) pushData(); }, 3000);

    // Visibility API
    const handleVisibility = () => {
      if (!document.hidden) {
        setTimeout(() => {
          loadData();
          checkPresence();
        }, 500);
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);

    // Push on user interaction (but rate-limited)
    let lastInteractionPush = 0;
    const syncOnInteraction = () => {
      const now = Date.now();
      if (now - lastInteractionPush > 2000) {
        lastInteractionPush = now;
        pushData();
      }
    };
    document.addEventListener('click', syncOnInteraction);
    document.addEventListener('touchstart', syncOnInteraction);

    return () => {
      destroyed = true;
      clearInterval(dataInterval);
      clearInterval(presenceInterval);
      clearInterval(pushInterval);
      document.removeEventListener('visibilitychange', handleVisibility);
      document.removeEventListener('click', syncOnInteraction);
      document.removeEventListener('touchstart', syncOnInteraction);
      window.removeEventListener('vdgo_data_changed', trackLocalMutation);
      fetch(roomUrl('presence/' + DEVICE_ID), { method: 'DELETE' }).catch(() => {});
    };
  }, [onData, pushData]);

  return { status, peerCount, pushData };
}

// MERGE helpers - merge incoming data with local instead of overwriting

function mergeDeletedKpiKeys(existing: string[], incoming: string[]): string[] {
  const set = new Set([...existing, ...incoming]);
  // Clean old entries (keep 24 hours)
  const oneDayAgo = Date.now() - 86400000;
  const result: string[] = [];
  for (const entry of set) {
    // If entry has timestamp (new format: "key@timestamp"), check age
    if (entry.includes('@')) {
      const ts = parseInt(entry.split('@')[1]);
      if (!isNaN(ts) && ts < oneDayAgo) continue;
    }
    result.push(entry);
  }
  // Save back to localStorage
  localStorage.setItem('vdgo_deleted_kpi_keys', JSON.stringify(result));
  return result;
}

function mergeData(type: string, incomingJson: string, handler: (type: string, data: any) => void) {
  try {
    const incoming = JSON.parse(incomingJson);
    const localRaw = localStorage.getItem(getLocalKey(type));
    const local = localRaw ? JSON.parse(localRaw) : (Array.isArray(incoming) ? [] : {});

    if (Array.isArray(incoming) && Array.isArray(local)) {
      // For arrays: merge by id, keep local items if not in incoming
      const merged = mergeArrays(local, incoming);
      handler(type, merged);
    } else {
      // For objects: just use incoming (simple replace)
      handler(type, incoming);
    }
  } catch (e) {
    handler(type, JSON.parse(incomingJson));
  }
}

function mergeKpi(incomingJson: string, handler: (type: string, data: any) => void, deletedKeys: string[]) {
  try {
    const incoming = JSON.parse(incomingJson);
    const localRaw = localStorage.getItem('vdgo_kpiSession');
    const local = localRaw ? JSON.parse(localRaw) : {};

    const deletedKeySet = new Set(deletedKeys.map(k => k.includes('@') ? k.split('@')[0] : k));

    // Merge key-by-key: filter out deleted keys
    const merged: Record<string, string> = {};

    // Start with incoming (peer data), filtering out deleted keys
    for (const key of Object.keys(incoming)) {
      if (!deletedKeySet.has(key)) {
        merged[key] = incoming[key];
      }
    }

    // Apply local changes (user edits), filtering out deleted keys
    for (const key of Object.keys(local)) {
      if (deletedKeySet.has(key)) continue; // Skip deleted keys
      if (local[key] && local[key].trim() !== '') {
        merged[key] = local[key]; // Keep local value
      } else if (local[key] === '' || (local[key] && local[key].trim() === '')) {
        // Local value is empty - this is a deletion signal
        // Mark it for deletion
        delete merged[key];
      }
    }

    handler('kpi', merged);
  } catch (e) {
    handler('kpi', JSON.parse(incomingJson));
  }
}

function mergeArrays(local: any[], incoming: any[]): any[] {
  // Load locally deleted IDs — these should NEVER come back
  const deletedIds = JSON.parse(localStorage.getItem('vdgo_deleted_ids') || '[]');
  const deletedIdSet = new Set(deletedIds.map((d: any) => d.id));
  // Clean old entries (keep 1 hour)
  const oneHourAgo = Date.now() - 3600000;
  const freshDeleted = deletedIds.filter((d: any) => d.deletedAt > oneHourAgo);
  if (freshDeleted.length !== deletedIds.length) {
    localStorage.setItem('vdgo_deleted_ids', JSON.stringify(freshDeleted));
  }

  // Filter out deleted items from incoming (peer may not know about deletion yet)
  const filteredIncoming = incoming.filter(item => !deletedIdSet.has(item.id));
  const result = [...filteredIncoming];
  const incomingIds = new Set(filteredIncoming.map(i => i.id));

  // Add local-only items that are newer than any incoming item
  const maxIncomingTs = filteredIncoming.reduce((max, i) => Math.max(max, i.createdAt || 0), 0);

  for (const localItem of local) {
    if (!localItem.id) continue;
    if (incomingIds.has(localItem.id)) continue;
    if (deletedIdSet.has(localItem.id)) continue; // Skip locally deleted
    const localTs = localItem.createdAt || 0;
    if (localTs > maxIncomingTs) {
      result.push(localItem);
    }
  }

  return result;
}

function getLocalKey(type: string): string {
  const map: Record<string, string> = {
    cases: 'vdgo_cases',
    notes: 'vdgo_notes',
    kpiCases: 'vdgo_kpiCases',
    duties: 'vdgo_duties',
    cash: 'vdgo_cash_registers_v1',
    timesheets: 'vdgo_timesheets',
    dispatcher: 'vdgo_dispatcher',
    excelFiles: 'vdgo_excel_files',
  };
  return map[type] || '';
}
