import { useState, useMemo, useRef, useCallback, useEffect } from 'react';
import { Save, TrendingUp, Users, BarChart3, Shield, X } from 'lucide-react';
import type { Worker } from '@/types';

interface KpiEntryData {
  workerId: string;
  day: number;
  value: string;
}

interface KpiSession {
  id: number;
  month: number;
  year: number;
  status: string;
  entries: KpiEntryData[];
}

interface Duty {
  workerId: string;
  dayType: string;
}

interface KpiDashboardViewProps {
  workers: Worker[];
  activeSession: KpiSession | null;
  kpiSessionEntries: Record<string, string>;
  onUpsertEntry: (sessionId: number, workerId: string, day: number, value: string) => void;
  onDeleteEntry: (sessionId: number, workerId: string, day: number) => void;
  onSaveSession: (sessionId: number, month: number, year: number) => void;
  toggleDuty?: (input: { month: number; year: number; workerId: string; dayType: "saturday" | "sunday" }) => void;
  clearDuties?: (input: { month: number; year: number }) => void;
  duties?: Duty[];
}

const MONTH_NAMES = ['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
const SPECIAL_CODES = ['В', 'ДО', 'ОТ', 'Б'];

const isWorkDay = (val: string) => {
  const t = val.trim();
  return t !== '' && !SPECIAL_CODES.includes(t) && !isNaN(parseFloat(t));
};

// Duty colors for saturday/sunday
const DUTY_COLORS: Record<string, { bg: string; text: string; border: string; label: string }> = {
  saturday: { bg: 'rgba(175,82,222,0.15)', text: '#AF52DE', border: 'rgba(175,82,222,0.3)', label: 'Сб' },
  sunday: { bg: 'rgba(255,149,0,0.15)', text: '#FF9500', border: 'rgba(255,149,0,0.3)', label: 'Вс' },
  both: { bg: 'linear-gradient(135deg, rgba(175,82,222,0.15) 0%, rgba(255,149,0,0.15) 100%)', text: '#8E8E93', border: 'rgba(175,82,222,0.2)', label: 'Сб+Вс' },
};

// Get weekends in month: returns array of { weekNum, saturday, sunday } with day numbers
function getWeekendsInMonth(month: number, year: number) {
  const daysInMonth = new Date(year, month, 0).getDate();
  const weekends: { weekNum: number; saturday: number | null; sunday: number | null }[] = [];
  let weekCount = 0;
  for (let d = 1; d <= daysInMonth; d++) {
    const date = new Date(year, month - 1, d);
    const dayOfWeek = date.getDay(); // 0=Sun, 6=Sat
    if (dayOfWeek === 6) {
      weekCount++;
      weekends.push({ weekNum: weekCount, saturday: d, sunday: null });
    } else if (dayOfWeek === 0 && weekends.length > 0) {
      weekends[weekends.length - 1].sunday = d;
    }
  }
  return weekends;
}

// Duty Modal Component - manages selection locally to avoid parent re-renders
const DutyModal = ({
  worker, month, year, onClose, onToggle, initialDayType,
}: {
  worker: Worker; month: number; year: number;
  onClose: () => void;
  onToggle: (input: { month: number; year: number; workerId: string; dayType: "saturday" | "sunday" }) => void;
  initialDayType: string | null;
}) => {
  const [selected, setSelected] = useState<string | null>(initialDayType);

  const handleToggle = (dayType: "saturday" | "sunday") => {
    if (selected === dayType) {
      // Same day clicked — remove
      setSelected(null);
      onToggle({ month, year, workerId: worker.id, dayType });
    } else {
      setSelected(dayType);
      onToggle({ month, year, workerId: worker.id, dayType });
    }
  };

  const handleRemove = () => {
    if (selected === 'saturday' || selected === 'sunday') {
      onToggle({ month, year, workerId: worker.id, dayType: selected });
      setSelected(null);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(4px)' }} onClick={onClose}>
      <div className="w-full max-w-[320px] rounded-lg p-4" style={{ background: 'var(--bg-secondary)', boxShadow: 'var(--shadow-floating)', border: '1px solid var(--border)' }} onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full flex items-center justify-center text-white text-[11px] font-semibold" style={{ background: 'var(--accent)' }}>{worker.initials}</div>
            <span className="text-[15px] font-semibold" style={{ color: 'var(--text-primary)' }}>{worker.name}</span>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-lg transition-colors" style={{ color: 'var(--text-secondary)' }}><X size={16} /></button>
        </div>
        <p className="text-[12px] mb-4" style={{ color: 'var(--text-secondary)' }}>Выберите день дежурства на {month}.{year}</p>

        <div className="flex gap-3">
          <button
            onClick={() => handleToggle('saturday')}
            className="flex-1 flex items-center justify-center gap-2 py-3 rounded-[10px] text-[13px] font-semibold transition-all active:scale-[0.97] border"
            style={selected === 'saturday'
              ? { background: DUTY_COLORS.saturday.bg, color: DUTY_COLORS.saturday.text, borderColor: DUTY_COLORS.saturday.border }
              : { background: 'var(--bg-secondary)', color: 'var(--text-secondary)', borderColor: 'var(--border)' }
            }
          >
            <Shield size={14} /> Суббота
            {selected === 'saturday' && <span>✓</span>}
          </button>
          <button
            onClick={() => handleToggle('sunday')}
            className="flex-1 flex items-center justify-center gap-2 py-3 rounded-[10px] text-[13px] font-semibold transition-all active:scale-[0.97] border"
            style={selected === 'sunday'
              ? { background: DUTY_COLORS.sunday.bg, color: DUTY_COLORS.sunday.text, borderColor: DUTY_COLORS.sunday.border }
              : { background: 'var(--bg-secondary)', color: 'var(--text-secondary)', borderColor: 'var(--border)' }
            }
          >
            <Shield size={14} /> Воскресенье
            {selected === 'sunday' && <span>✓</span>}
          </button>
        </div>

        {selected && (
          <button 
            onClick={handleRemove}
            className="w-full mt-3 py-2 text-[12px] font-medium rounded-[10px] transition-all"
            style={{ background: 'rgba(255,59,48,0.08)', color: '#FF3B30' }}
          >
            Снять дежурство
          </button>
        )}

        <button onClick={onClose} className="w-full mt-3 py-2.5 text-[13px] font-medium rounded-[10px] transition-all active:scale-[0.97]" style={{ background: 'var(--input-bg)', color: 'var(--text-primary)' }}>Готово</button>
      </div>
    </div>
  );
};

export const KpiDashboardView = ({ workers, activeSession, onUpsertEntry, onDeleteEntry, onSaveSession, toggleDuty, clearDuties, duties: propDuties }: KpiDashboardViewProps) => {
  const now = new Date();
  const [month, setMonth] = useState(activeSession?.month ?? (now.getMonth() + 1));
  const [year, setYear] = useState(activeSession?.year ?? now.getFullYear());
  const [saved, setSaved] = useState(false);
  const [dutyModalWorker, setDutyModalWorker] = useState<Worker | null>(null);

  // Local entries state — allows fast typing + sync from server
  const [localEntries, setLocalEntries] = useState<Record<string, string>>({});
  // Track which cell is being edited (don't overwrite from server)
  const editingRef = useRef<Set<string>>(new Set());

  const inputRefs = useRef<Record<string, HTMLInputElement>>({});
  const debounceTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  const daysInMonth = useMemo(() => new Date(year, month, 0).getDate(), [month, year]);
  const days = useMemo(() => Array.from({ length: daysInMonth }, (_, i) => i + 1), [daysInMonth]);
  const workerList = useMemo(() => [...workers].sort((a, b) => a.name.localeCompare(b.name)), [workers]);

  // Duties from props
  const duties = propDuties ?? [];

  // Build entries map from active session
  const serverEntries = useMemo(() => {
    const map: Record<string, string> = {};
    if (activeSession) {
      for (const e of activeSession.entries) {
        map[`${e.workerId}_${e.day}`] = e.value;
      }
    }
    return map;
  }, [activeSession]);

  // Sync server entries to local (skip cells currently being edited)
  useEffect(() => {
    setLocalEntries(prev => {
      const next = { ...prev };
      for (const [key, value] of Object.entries(serverEntries)) {
        if (!editingRef.current.has(key)) {
          next[key] = value;
        }
      }
      // Remove keys that don't exist on server anymore
      for (const key of Object.keys(next)) {
        if (!(key in serverEntries) && !editingRef.current.has(key)) {
          delete next[key];
        }
      }
      return next;
    });
  }, [serverEntries]);

  const getKey = (workerId: string, day: number) => `${workerId}_${day}`;

  const normalizeValue = (val: string): string => {
    const t = val.trim();
    const upper = t.toUpperCase();
    if (upper === 'В' || upper === 'ДО' || upper === 'ОТ' || upper === 'Б') return upper;
    return t;
  };

  // Auto-save: upsert entry to server with debounce
  const handleChange = (workerId: string, day: number, value: string) => {
    const normalized = normalizeValue(value);
    const key = getKey(workerId, day);

    // Mark as editing
    editingRef.current.add(key);

    // Update local immediately
    setLocalEntries(prev => ({ ...prev, [key]: normalized }));

    // Clear previous debounce timer
    if (debounceTimers.current[key]) {
      clearTimeout(debounceTimers.current[key]);
    }

    // Debounce: save after 400ms of no typing
    debounceTimers.current[key] = setTimeout(() => {
      editingRef.current.delete(key);
      if (!activeSession) return;

      if (normalized === '') {
        onDeleteEntry(activeSession.id, workerId, day);
      } else {
        onUpsertEntry(activeSession.id, workerId, day, normalized);
      }
    }, 400);
  };

  // Arrow key navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent, wIdx: number, d: number) => {
    const workersCount = workerList.length;
    const daysCount = days.length;
    let nextW = wIdx, nextD = d;

    if (e.key === 'ArrowRight') { nextD = Math.min(d + 1, daysCount); e.preventDefault(); }
    else if (e.key === 'ArrowLeft') { nextD = Math.max(d - 1, 1); e.preventDefault(); }
    else if (e.key === 'ArrowDown') { nextW = Math.min(wIdx + 1, workersCount - 1); e.preventDefault(); }
    else if (e.key === 'ArrowUp') { nextW = Math.max(wIdx - 1, 0); e.preventDefault(); }

    if (nextW !== wIdx || nextD !== d) {
      const nextKey = getKey(workerList[nextW].id, nextD);
      const nextInput = inputRefs.current[nextKey];
      if (nextInput) { nextInput.focus(); nextInput.select(); }
    }
  }, [workerList, days]);

  const handleSave = () => {
    if (!activeSession) return;
    // Flush all pending saves first
    for (const timer of Object.values(debounceTimers.current)) {
      clearTimeout(timer);
    }
    debounceTimers.current = {};
    editingRef.current.clear();

    onSaveSession(activeSession.id, month, year);
    setLocalEntries({});
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  // Averages
  const averages = useMemo(() => {
    const perWorker = workerList.map(w => {
      let sum = 0, workDays = 0;
      for (let d = 1; d <= daysInMonth; d++) {
        const val = localEntries[getKey(w.id, d)] || '';
        if (isWorkDay(val)) { sum += parseFloat(val); workDays++; }
      }
      return { workerId: w.id, name: w.name, average: workDays > 0 ? +(sum / workDays).toFixed(1) : 0, total: sum, workDays };
    });
    let totalSum = 0, totalWorkDays = 0;
    for (const pw of perWorker) { totalSum += pw.total; totalWorkDays += pw.workDays; }
    return { perWorker, brigadeAvg: totalWorkDays > 0 ? +(totalSum / totalWorkDays).toFixed(1) : 0, totalSum, totalWorkDays };
  }, [localEntries, workerList, daysInMonth]);

  const getCellBg = (val: string) => {
    const t = val.trim();
    if (t === '') return 'bg-[var(--surface)] focus:bg-[var(--input-bg)]';
    if (t === 'В') return 'bg-[#FFEB3B] text-[#5D4037]';
    if (t === 'ДО') return 'bg-[#FFCC80] text-[#BF360C]';
    if (t === 'ОТ') return 'bg-[#81D4FA] text-[#01579B]';
    if (t === 'Б') return 'bg-[#EF9A9A] text-[#B71C1C]';
    return 'bg-[#34C759]/15 text-[#1d8c3b] focus:bg-[#34C759]/25';
  };

  // Sync month/year when active session changes
  useEffect(() => {
    if (activeSession) {
      setMonth(activeSession.month);
      setYear(activeSession.year);
    }
  }, [activeSession?.id]);

  // Get duty info for a worker
  const getWorkerDuties = (workerId: string) => duties.filter(d => d.workerId === workerId);
  const hasDuty = (workerId: string) => getWorkerDuties(workerId).length > 0;

  // Get worker row background based on duty
  const getWorkerRowStyle = (workerId: string) => {
    const d = duties.find(d => d.workerId === workerId);
    if (!d) return {};
    if (d.dayType === 'saturday') return { background: DUTY_COLORS.saturday.bg };
    if (d.dayType === 'sunday') return { background: DUTY_COLORS.sunday.bg };
    return {};
  };

  return (
    <div className="h-full flex flex-col p-2 md:p-4 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between mb-2 flex-shrink-0 flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <h2 className="text-[16px] md:text-[18px] font-semibold text-[var(--text-primary)] tracking-tight">KPI планшет</h2>
        </div>
        <div className="flex items-center gap-1.5 md:gap-2">
          <select value={month} onChange={e => setMonth(Number(e.target.value))}
            className="bg-[var(--surface)] border border-[var(--input-border)] rounded-[8px] px-2 py-1.5 text-[12px] md:text-[13px] focus:outline-none focus:border-[#0071E3]">
            {MONTH_NAMES.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
          </select>
          <input type="number" value={year} onChange={e => setYear(Number(e.target.value))}
            className="w-[55px] md:w-[70px] bg-[var(--surface)] border border-[var(--input-border)] rounded-[8px] px-2 py-1.5 text-[12px] md:text-[13px] focus:outline-none focus:border-[#0071E3]" />
          {toggleDuty && (
            <button onClick={() => { if (clearDuties && confirm('Очистить все дежурства?')) clearDuties({ month, year }); }}
              className="px-2 md:px-3 py-1.5 text-[11px] font-medium rounded-[8px] transition-all"
              style={{ background: 'rgba(175,82,222,0.1)', color: '#AF52DE' }} title="Очистить дежурства">
              <Shield size={13} />
            </button>
          )}
          <button onClick={handleSave}
            className={`flex items-center gap-1 px-2 md:px-3 py-1.5 text-[11px] md:text-[12px] font-medium rounded-[8px] transition-all active:scale-[0.97] ${saved ? 'bg-[#34C759] text-white' : 'bg-[#0071E3] hover:bg-[#0077ED] text-white'}`}>
            <Save size={12} className="md:hidden" /><Save size={13} className="hidden md:block" /> {saved ? '✓' : 'Сохр.'}
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-1.5 md:gap-2 mb-2 flex-shrink-0">
        <div className="bg-[var(--surface)] rounded-lg border border-[var(--border)] p-2 md:p-2.5 flex items-center gap-1.5 md:gap-2">
          <div className="w-6 h-6 md:w-7 md:h-7 rounded-lg bg-[#0071E3]/10 flex items-center justify-center flex-shrink-0"><TrendingUp size={12} className="text-[#0071E3] md:hidden" /><TrendingUp size={14} className="text-[#0071E3] hidden md:block" /></div>
          <div><p className="text-[9px] md:text-[10px] text-[var(--text-secondary)]">Среднее</p><p className="text-[14px] md:text-[16px] font-bold text-[var(--text-primary)] leading-tight">{averages.brigadeAvg}</p></div>
        </div>
        <div className="bg-[var(--surface)] rounded-lg border border-[var(--border)] p-2 md:p-2.5 flex items-center gap-1.5 md:gap-2">
          <div className="w-6 h-6 md:w-7 md:h-7 rounded-lg bg-[#34C759]/10 flex items-center justify-center flex-shrink-0"><BarChart3 size={12} className="text-[#34C759] md:hidden" /><BarChart3 size={14} className="text-[#34C759] hidden md:block" /></div>
          <div><p className="text-[9px] md:text-[10px] text-[var(--text-secondary)]">Работ</p><p className="text-[14px] md:text-[16px] font-bold text-[var(--text-primary)] leading-tight">{averages.totalSum}</p></div>
        </div>
        <div className="bg-[var(--surface)] rounded-lg border border-[var(--border)] p-2 md:p-2.5 flex items-center gap-1.5 md:gap-2">
          <div className="w-6 h-6 md:w-7 md:h-7 rounded-lg bg-[#FF9500]/10 flex items-center justify-center flex-shrink-0"><Users size={12} className="text-[#FF9500] md:hidden" /><Users size={14} className="text-[#FF9500] hidden md:block" /></div>
          <div><p className="text-[9px] md:text-[10px] text-[var(--text-secondary)]">Дни</p><p className="text-[14px] md:text-[16px] font-bold text-[var(--text-primary)] leading-tight">{averages.totalWorkDays}</p></div>
        </div>
      </div>

      {/* Duty legend */}
      {toggleDuty && (
        <div className="flex items-center gap-2 md:gap-3 mb-1.5 flex-shrink-0 flex-wrap">
          <span className="text-[9px] md:text-[10px] text-[var(--text-secondary)] font-medium">Дежурства:</span>
          <span className="flex items-center gap-1 text-[9px] md:text-[10px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] inline-block" style={{ background: DUTY_COLORS.saturday.bg, border: `1px solid ${DUTY_COLORS.saturday.border}` }} /> <strong style={{ color: DUTY_COLORS.saturday.text }}>Суббота</strong></span>
          <span className="flex items-center gap-1 text-[9px] md:text-[10px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] inline-block" style={{ background: DUTY_COLORS.sunday.bg, border: `1px solid ${DUTY_COLORS.sunday.border}` }} /> <strong style={{ color: DUTY_COLORS.sunday.text }}>Воскресенье</strong></span>
          <span className="text-[9px] md:text-[10px] text-[var(--text-tertiary)]">Кликните на слесаря</span>
        </div>
      )}

      {/* Table - compact to fit all workers on screen */}
      <div className="flex-1 bg-[var(--surface)] rounded-xl border border-[var(--border)] shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto flex-1 -webkit-overflow-scrolling-touch">
          <table className="w-full border-collapse" style={{ minWidth: days.length * 24 + 120 }}>
            <thead className="sticky top-0 z-10">
              <tr style={{ background: 'var(--input-bg)', borderBottom: '1px solid var(--border)' }}>
                <th className="text-left px-1 md:px-1.5 py-[2px] md:py-1 text-[9px] md:text-[10px] font-semibold text-[var(--text-secondary)] uppercase tracking-[0.05em] sticky left-0 z-20 border-r border-[var(--border)] w-[72px] md:w-[90px]" style={{ background: 'var(--input-bg)' }}>Слесарь</th>
                {days.map(d => (
                  <th key={d} className="text-center px-[1px] md:px-[2px] py-[2px] md:py-1 text-[8px] md:text-[9px] font-semibold text-[var(--text-secondary)] w-[20px] md:w-[24px] border-r border-[var(--border)]">{d}</th>
                ))}
                <th className="text-center px-[2px] md:px-1 py-[2px] md:py-1 text-[8px] md:text-[9px] font-semibold text-[var(--text-secondary)] w-[26px] md:w-[30px]">Ср</th>
              </tr>
            </thead>
            <tbody>
              {workerList.map((w, wIdx) => {
                const avg = averages.perWorker.find(a => a.workerId === w.id);
                const rowStyle = getWorkerRowStyle(w.id);
                return (
                  <tr key={w.id} className="border-b border-[var(--border)] hover:bg-[var(--input-bg)]/30 transition-colors" style={rowStyle}>
                    <td
                      className="px-1 md:px-1.5 py-[1px] md:py-[2px] text-[9px] md:text-[10px] font-medium text-[var(--text-primary)] sticky left-0 z-10 border-r border-[var(--border)] whitespace-nowrap leading-tight cursor-pointer"
                      style={{ background: 'var(--surface)', ...(hasDuty(w.id) ? rowStyle : {}) }}
                      onClick={() => {
                      try {
                        if (toggleDuty) setDutyModalWorker(w);
                      } catch (err) {
                        console.error('Duty click error:', err);
                        alert('Ошибка: ' + (err as Error).message);
                      }
                    }}
                    >
                      <div className="flex items-center gap-0.5">
                        {hasDuty(w.id) && <Shield size={8} style={{ color: getWorkerDuties(w.id).some(d => d.dayType === 'saturday') ? DUTY_COLORS.saturday.text : DUTY_COLORS.sunday.text, flexShrink: 0 }} />}
                        <span className="truncate">{w.name}</span>
                      </div>
                    </td>
                    {days.map(d => {
                      const val = localEntries[getKey(w.id, d)] || '';
                      return (
                        <td key={d} className="p-[1px] border-r border-[var(--border)]">
                          <input
                            ref={el => { if (el) inputRefs.current[getKey(w.id, d)] = el; }}
                            type="text"
                            value={val}
                            onChange={e => handleChange(w.id, d, e.target.value)}
                            onKeyDown={e => handleKeyDown(e, wIdx, d)}
                            onFocus={e => e.currentTarget.select()}
                            maxLength={3}
                            className={`w-full h-[18px] md:h-[20px] text-center text-[8px] md:text-[10px] font-semibold rounded-[1px] border border-transparent focus:border-[#0071E3] focus:ring-[1px] focus:ring-[#0071E3]/15 outline-none transition-all ${getCellBg(val)}`}
                          />
                        </td>
                      );
                    })}
                    <td className="text-center px-[2px] md:px-1 py-[1px] md:py-[2px]">
                      <span className={`text-[8px] md:text-[10px] font-bold ${(avg?.average || 0) > 0 ? 'text-[#0071E3]' : 'text-[var(--text-tertiary)]'}`}>
                        {avg?.average || '-'}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center gap-2 md:gap-3 mt-1.5 flex-shrink-0 flex-wrap">
        <span className="text-[9px] md:text-[11px] text-[var(--text-secondary)] font-medium">Легенда:</span>
        <span className="flex items-center gap-1 text-[9px] md:text-[11px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] bg-[#34C759]/25 border border-[#34C759] inline-block" /> <strong className="text-[#1d8c3b]">число</strong></span>
        <span className="flex items-center gap-1 text-[9px] md:text-[11px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] bg-[#FFEB3B] border border-[#FBC02D] inline-block" /> <strong className="text-[#5D4037]">В</strong></span>
        <span className="flex items-center gap-1 text-[9px] md:text-[11px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] bg-[#FFCC80] border border-[#FF9800] inline-block" /> <strong className="text-[#E65100]">ДО</strong></span>
        <span className="flex items-center gap-1 text-[9px] md:text-[11px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] bg-[#81D4FA] border border-[#03A9F4] inline-block" /> <strong className="text-[#0277BD]">ОТ</strong></span>
        <span className="flex items-center gap-1 text-[9px] md:text-[11px]"><span className="w-3 h-3 md:w-3.5 md:h-3.5 rounded-[3px] bg-[#EF9A9A] border border-[#F44336] inline-block" /> <strong className="text-[#C62828]">Б</strong></span>
      </div>

      {/* Duty Modal */}
      {dutyModalWorker && (
        <DutyModal
          key={dutyModalWorker.id}
          worker={dutyModalWorker}
          month={month}
          year={year}
          onClose={() => setDutyModalWorker(null)}
          onToggle={toggleDuty}
          initialDayType={getWorkerDuties(dutyModalWorker.id).find(d => d.dayType === 'saturday' || d.dayType === 'sunday')?.dayType ?? null}
        />
      )}
    </div>
  );
};
